# GENERATED by ml/src/features/export/vendor.py from ml/src/features/. DO NOT EDIT: change the original and re-run `make export-model`.
"""Hand-made "context" features computed from the raw message and its sender.

The text model alone cannot tell a REAL M-Pesa confirmation from a FAKE one: the words are
identical. What differs is who sent it. These five 0/1 features carry that context into the
model. The Kotlin app and the simulator compute exactly the same five (see shared/contracts.md).
"""
import re

FEATURE_NAMES = ["sender_verified", "sender_personal_number", "has_link", "mpesa_style", "fake_mpesa"]

_PERSONAL_NUMBER = re.compile(r"(?:\+?254|0)[17][0-9]{8}")
_LINK = re.compile(r"https?://|www\.|\b(?:bit\.ly|tinyurl\.com|t\.co|cutt\.ly|goo\.gl)/", re.IGNORECASE)
# 10 capitals/digits with at least one of each, e.g. QK7RT2XY9P (case-sensitive on purpose).
_TRANSACTION_CODE = re.compile(
    r"(?<![A-Za-z0-9])(?=[A-Z0-9]{10}(?![A-Za-z0-9]))(?=[A-Z0-9]*[A-Z])(?=[A-Z0-9]*[0-9])[A-Z0-9]{10}"
)
_CONFIRMED = re.compile(r"confirmed|imethibitishwa", re.IGNORECASE)
_KSH = re.compile(r"ksh", re.IGNORECASE)


def metadata_features(text: str, sender: str | None, verified: set[str]) -> list[float]:
    """Return the five features in FEATURE_NAMES order. `sender` is None for pasted/shared text."""
    sender = (sender or "").strip()
    is_verified = sender.upper() in verified
    is_personal = bool(_PERSONAL_NUMBER.fullmatch(sender))
    has_link = bool(_LINK.search(text))
    mpesa_style = bool(_TRANSACTION_CODE.search(text) and _CONFIRMED.search(text) and _KSH.search(text))
    # Looks like an M-Pesa confirmation but did not come from M-Pesa. Pasted text (no sender)
    # is judged on its words alone, so it never fires this feature.
    fake_mpesa = mpesa_style and sender != "" and not is_verified
    return [float(is_verified), float(is_personal), float(has_link), float(mpesa_style), float(fake_mpesa)]
